from pathlib import Path
import py_compile

ROOT=Path.cwd()
SUB=ROOT/"qseries_v2/oracle_strategy_intelligence/solana_money/qarb_clean_bot"
ENG=SUB/"engine.py"
if not ENG.is_file():
    raise SystemExit("[FAIL] QARB clean bot missing")

src=ENG.read_text(encoding="utf-8")
if "def raw_candidate_universe(root):" not in src or "_cross_cache=" not in src:
    raise SystemExit("[FAIL] QARB-002B is required")

HOT=SUB/"hotpath.py"
HOT.write_text('from dataclasses import dataclass\nfrom queue import SimpleQueue, Empty\nfrom time import perf_counter_ns\n\nMAX_ROUTE_AGE_MS = 750.0\nMIN_NET_BPS = 20.0\n\n@dataclass(frozen=True)\nclass QuoteUpdate:\n    token: str\n    pump_pool: str\n    meteora_pool: str\n    venue: str\n    direction: str\n    size_sol: float\n    end_sol: float\n    observed_ns: int\n    sequence: int = 0\n\n@dataclass(frozen=True)\nclass HotSignal:\n    token: str\n    direction: str\n    size_sol: float\n    end_sol: float\n    net_sol: float\n    net_bps: float\n    route_age_ms: float\n    decision_us: float\n    execution_authority: bool = False\n\nclass HotBook:\n    def __init__(self, max_age_ms=MAX_ROUTE_AGE_MS, min_net_bps=MIN_NET_BPS, clock_ns=perf_counter_ns):\n        self.max_age_ms = float(max_age_ms)\n        self.min_net_bps = float(min_net_bps)\n        self.clock_ns = clock_ns\n        self.pump = {}\n        self.meteora = {}\n        self.queue = SimpleQueue()\n\n    def publish(self, update):\n        self.queue.put(update)\n\n    def drain_once(self):\n        try:\n            return self.ingest(self.queue.get_nowait())\n        except Empty:\n            return None\n\n    def ingest(self, update):\n        key = (\n            update.token,\n            update.pump_pool,\n            update.meteora_pool,\n            update.direction,\n            float(update.size_sol),\n        )\n        if update.venue == "PUMPSWAP":\n            self.pump[key] = update\n        elif update.venue == "METEORA_DLMM":\n            self.meteora[key] = update\n        else:\n            return None\n\n        p = self.pump.get(key)\n        m = self.meteora.get(key)\n        if p is None or m is None:\n            return None\n\n        start_ns = self.clock_ns()\n        now_ns = self.clock_ns()\n        age_ms = max(now_ns - p.observed_ns, now_ns - m.observed_ns) / 1_000_000.0\n        if age_ms > self.max_age_ms:\n            return None\n\n        start_sol = float(update.size_sol)\n        end_sol = float(m.end_sol if update.direction == "PUMP_TO_METEORA" else p.end_sol)\n        net_sol = end_sol - start_sol\n        net_bps = (net_sol / start_sol) * 10000.0 if start_sol > 0 else -1e18\n        if net_bps < self.min_net_bps:\n            return None\n\n        return HotSignal(\n            token=update.token,\n            direction=update.direction,\n            size_sol=start_sol,\n            end_sol=end_sol,\n            net_sol=net_sol,\n            net_bps=net_bps,\n            route_age_ms=age_ms,\n            decision_us=(self.clock_ns() - start_ns) / 1000.0,\n            execution_authority=False,\n        )\n\ndef benchmark(iterations=5000):\n    book = HotBook()\n    now = book.clock_ns()\n    book.ingest(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",0.05,0.054,now,1))\n    samples = []\n    last = None\n    for i in range(int(iterations)):\n        t = book.clock_ns()\n        u = QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",0.05,0.054,t,i+2)\n        t0 = book.clock_ns()\n        last = book.ingest(u)\n        samples.append((book.clock_ns()-t0)/1000.0)\n    samples.sort()\n    return {\n        "iterations": len(samples),\n        "p50_us": samples[len(samples)//2],\n        "p99_us": samples[min(len(samples)-1, int(len(samples)*0.99))],\n        "under_750ms": bool(last is not None and last.route_age_ms <= 750.0),\n    }\n',encoding="utf-8")
py_compile.compile(str(HOT),doraise=True)

TEST=ROOT/"test_qarb_004c_sub750_event_hotpath.py"
TEST.write_text('import inspect\nimport unittest\nfrom time import perf_counter_ns\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.hotpath import HotBook, QuoteUpdate, benchmark\n\nclass T(unittest.TestCase):\n    def test_fresh_positive(self):\n        b=HotBook()\n        now=perf_counter_ns()\n        self.assertIsNone(b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",0.05,0.054,now,1)))\n        s=b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",0.05,0.054,now,2))\n        self.assertIsNotNone(s)\n        self.assertLessEqual(s.route_age_ms,750.0)\n        print("[PASS] fresh profitable Pump->Meteora signal admitted")\n\n    def test_stale_rejected(self):\n        b=HotBook()\n        old=perf_counter_ns()-800_000_000\n        b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","PUMP_TO_METEORA",0.05,0.054,old,1))\n        s=b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","PUMP_TO_METEORA",0.05,0.054,perf_counter_ns(),2))\n        self.assertIsNone(s)\n        print("[PASS] >750ms route rejected")\n\n    def test_reverse(self):\n        b=HotBook()\n        now=perf_counter_ns()\n        b.ingest(QuoteUpdate("T","P","M","METEORA_DLMM","METEORA_TO_PUMP",0.05,0.054,now,1))\n        s=b.ingest(QuoteUpdate("T","P","M","PUMPSWAP","METEORA_TO_PUMP",0.05,0.054,now,2))\n        self.assertIsNotNone(s)\n        print("[PASS] reverse Meteora->Pump supported")\n\n    def test_no_io_in_ingest(self):\n        src=inspect.getsource(HotBook.ingest).lower()\n        for bad in ("rpc(","urllib","requests","open(","sleep(","subprocess","path("):\n            self.assertNotIn(bad,src)\n        print("[PASS] hot ingest has no network/filesystem/sleep")\n\n    def test_benchmark(self):\n        r=benchmark(5000)\n        self.assertTrue(r["under_750ms"])\n        self.assertLess(r["p99_us"],750000)\n        print("[PASS] p99_us=%.2f"%r["p99_us"])\n\nif __name__=="__main__":\n    unittest.main(verbosity=2)\n',encoding="utf-8")
py_compile.compile(str(TEST),doraise=True)

RUN=ROOT/"run_qarb_004c_sub750_event_hotpath.py"
RUN.write_text('from qseries_v2.oracle_strategy_intelligence.solana_money.qarb_clean_bot.hotpath import benchmark\nr=benchmark(5000)\nprint("[QARB-004C] SUB-750MS EVENT HOT PATH")\nprint("[BENCH] iterations=%d p50_us=%.2f p99_us=%.2f under_750ms=%s"%(r["iterations"],r["p50_us"],r["p99_us"],r["under_750ms"]))\nprint("[INTERLEG] atomic target logical_gap_ms=0")\nprint("[MODE] execution_authority=FALSE")\n',encoding="utf-8")
py_compile.compile(str(RUN),doraise=True)

print("[PASS] QARB-004C installed directly on QARB-002B")
print("[LATENCY] hard route age <=750ms")
print("[HOT_PATH] in-memory event decision only")
print("[NO_HOT_IO] no REST/RPC/filesystem/sleep")
print("[INTERLEG] atomic target logical gap=0ms")
print("[MODE] execution_authority=FALSE")
